<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { listen, type UnlistenFn } from '@tauri-apps/api/event'
import { getCurrentWindow } from '@tauri-apps/api/window'
import type { PetState } from '../types'
import { chooseIdleActivity, type PetIdleActivity } from '../services/petLife'
import { buildPetMood, moodLabel, type PetMood } from '../services/petMood'
import { characterLabels, defaultPetSettings, loadPetSettings, motionMultiplier, personalityLabels, personalityMotionMultiplier, personalitySleepMultiplier, petCharacters, savePetSettings, type PetSettings } from '../services/petSettings'

type NativeInputEvent = { kind: 'key'|'mouseMove'|'wheel'; x?: number|null; y?: number|null; deltaX?: number|null; deltaY?: number|null }
const props=withDefaults(defineProps<{state:PetState;draggable?:boolean;pointerDirection?:'left'|'right';choreographyAction?:string}>(),{draggable:true,pointerDirection:'right',choreographyAction:''})
const emit=defineEmits<{(e:'pet'):void;(e:'menu'):void}>()

const eyeX=ref(0),eyeY=ref(0),isPetting=ref(false),idleActivity=ref<PetIdleActivity>('rest'),mood=ref<PetMood>('calm'),energy=ref(78),affection=ref(45),roamX=ref(0),roamY=ref(0),lastInteractionAt=ref(Date.now()),recentPets=ref(0),settingsOpen=ref(false)
const settings=ref<PetSettings>(loadPetSettings()),draft=ref<PetSettings>({...settings.value})
const mochi=ref(false),hunting=ref(false),kneading=ref(false),overheat=ref(false),scrolling=ref(false),reminderBubble=ref(''),purr=ref(false),nativeInputState=ref('Waiting for native input…')
const doctorOpen=ref(false),doctorRunning=ref(false),doctorSeconds=ref(0),doctorResult=ref(''),doctorKeys=ref(0),doctorWheels=ref(0),doctorMoves=ref(0)
let cycleIndex=0,lifeTimer:number|undefined,reminderTimer:number|undefined,huntTimer:number|undefined,kneadTimer:number|undefined,overheatTimer:number|undefined,scrollTimer:number|undefined,purrTimer:number|undefined,doctorTimer:number|undefined
let lastPointer={x:0,y:0,t:performance.now()},keyHits:number[]=[]
let lastStretchAt=Date.now(),lastWaterAt=Date.now(),nativeBridgeSeen=false,audioContext:AudioContext|undefined
let unlistenNative:UnlistenFn|undefined,unlistenNativeStatus:UnlistenFn|undefined,unlistenOpenSettings:UnlistenFn|undefined

const autonomous=computed(()=>props.state==='idle'||props.state==='sleeping')
const reactionsAllowed=computed(()=>props.state!=='teaching'&&props.state!=='error')
const showThought=computed(()=>props.state==='thinking'||props.choreographyAction==='think'),showSparkles=computed(()=>props.state==='success'||props.choreographyAction==='celebrate')
const petStyle=computed(()=>{
  const style:Record<string,string>={}
  if(autonomous.value&&settings.value.autonomousMovement)style.transform=`translate(${roamX.value}px, ${roamY.value}px)`
  if(settings.value.customFurColor)style['--nyan-custom-fur']=settings.value.customFurColor
  if(settings.value.customEyeColor)style['--nyan-custom-eye']=settings.value.customEyeColor
  return style
})
const lifeTitle=computed(()=>`${settings.value.name} · ${characterLabels[settings.value.character]} · ${personalityLabels[settings.value.personality]} · Mood: ${moodLabel(mood.value)} · Energy ${energy.value}% · Affection ${affection.value}%`)
const sleepAfterMs=computed(()=>settings.value.sleepAfterMinutes*60000*personalitySleepMultiplier(settings.value.personality))
const ownerPrefix=computed(()=>settings.value.ownerName?`${settings.value.ownerName}, `:'')

function registerInteraction(){lastInteractionAt.value=Date.now();if(props.state==='sleeping')idleActivity.value='rest'}
function trackEyes(e:MouseEvent){registerInteraction();const r=(e.currentTarget as HTMLElement).getBoundingClientRect(),x=(e.clientX-(r.left+r.width/2))/r.width,y=(e.clientY-(r.top+r.height/2))/r.height;eyeX.value=Math.max(-3,Math.min(3,x*8));eyeY.value=Math.max(-2,Math.min(2,y*6))}
function resetEyes(){eyeX.value=0;eyeY.value=0}
async function startDrag(e:MouseEvent){registerInteraction();if(!props.draggable||e.button!==0)return;mochi.value=true;window.setTimeout(()=>mochi.value=false,900);try{await getCurrentWindow().startDragging()}catch{}}
function ensureAudio(){if(!audioContext)audioContext=new AudioContext();if(audioContext.state==='suspended')void audioContext.resume()}
function tone(freq:number,duration:number,volume=1,type:OscillatorType='sine'){if(settings.value.soundVolume<=0)return;try{ensureAudio();if(!audioContext)return;const o=audioContext.createOscillator(),g=audioContext.createGain(),now=audioContext.currentTime;o.type=type;o.frequency.setValueAtTime(freq,now);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(Math.max(.0001,settings.value.soundVolume/100*.06*volume),now+.02);g.gain.exponentialRampToValueAtTime(.0001,now+duration);o.connect(g);g.connect(audioContext.destination);o.start(now);o.stop(now+duration+.03)}catch{}}
function playPurr(){tone(74,.22,.7,'sine');setTimeout(()=>tone(62,.24,.6,'sine'),120)}
function playMeow(){tone(520,.12,.9,'triangle');setTimeout(()=>tone(390,.2,.8,'triangle'),90)}
function pet(e:MouseEvent){registerInteraction();recentPets.value=Math.min(8,recentPets.value+1);isPetting.value=true;const r=(e.currentTarget as HTMLElement).getBoundingClientRect(),onHead=e.clientY-r.top<105;purr.value=onHead;if(onHead)playPurr();emit('pet');window.setTimeout(()=>isPetting.value=false,700);if(purrTimer)clearTimeout(purrTimer);purrTimer=window.setTimeout(()=>purr.value=false,1300)}
function showSettings(){if(!props.draggable)return;draft.value={...settings.value};settingsOpen.value=true;registerInteraction()}
function openSettings(e:MouseEvent){e.preventDefault();showSettings()}
function applySettings(){settings.value=savePetSettings(draft.value);settingsOpen.value=false;registerInteraction();lastStretchAt=lastWaterAt=Date.now();updateLife()}
function externalSettings(e:Event){const d=(e as CustomEvent<PetSettings>).detail;if(d)settings.value={...d}}

function updateLife(){if(!autonomous.value){idleActivity.value='rest';roamX.value=roamY.value=0;return}const inactiveMs=Date.now()-lastInteractionAt.value,life=chooseIdleActivity(inactiveMs,cycleIndex,sleepAfterMs.value),snap=buildPetMood({inactiveMs,recentPets:recentPets.value,cycleIndex});idleActivity.value=life.activity;mood.value=settings.value.personality==='playful'&&recentPets.value>0?'playful':settings.value.personality==='sleepy'&&inactiveMs>45000?'sleepy':snap.mood;energy.value=snap.energy;affection.value=snap.affection;const movement=motionMultiplier(settings.value.motionLevel)*personalityMotionMultiplier(settings.value.personality);roamX.value=!settings.value.autonomousMovement||life.asleep?0:Math.round(snap.roamX*movement);roamY.value=life.asleep?3:!settings.value.autonomousMovement?0:Math.round(snap.roamY*movement);cycleIndex++;if(cycleIndex%3===0&&recentPets.value>0)recentPets.value--}
function processMouseMove(x:number,y:number){if(doctorRunning.value)doctorMoves.value++;if(!settings.value.cursorHunting||!reactionsAllowed.value)return;const now=performance.now(),dt=Math.max(8,now-lastPointer.t),dx=x-lastPointer.x,dy=y-lastPointer.y,speed=Math.hypot(dx,dy)/dt*1000;lastPointer={x,y,t:now};if(speed>950){hunting.value=true;registerInteraction();if(huntTimer)clearTimeout(huntTimer);huntTimer=window.setTimeout(()=>hunting.value=false,950)}}
function globalMouseMove(e:MouseEvent){if(nativeBridgeSeen)return;processMouseMove(e.screenX||e.clientX,e.screenY||e.clientY)}
function keyDown(){if(doctorRunning.value)doctorKeys.value++;if(!settings.value.keyboardReactions||!reactionsAllowed.value)return;const now=Date.now();keyHits=keyHits.filter(t=>now-t<1800);keyHits.push(now);kneading.value=true;if(kneadTimer)clearTimeout(kneadTimer);kneadTimer=window.setTimeout(()=>kneading.value=false,300);if(keyHits.length>=12){overheat.value=true;if(overheatTimer)clearTimeout(overheatTimer);overheatTimer=window.setTimeout(()=>{overheat.value=false;keyHits=[]},2600)}}
function webKeyDown(){if(nativeBridgeSeen)return;keyDown()}
function wheel(){if(doctorRunning.value)doctorWheels.value++;if(!settings.value.scrollReactions||!reactionsAllowed.value)return;scrolling.value=true;if(scrollTimer)clearTimeout(scrollTimer);scrollTimer=window.setTimeout(()=>scrolling.value=false,1000)}
function webWheel(){if(nativeBridgeSeen)return;wheel()}
function nativeInput(payload:NativeInputEvent){nativeBridgeSeen=true;nativeInputState.value='System-wide reactions active';if(payload.kind==='key')keyDown();else if(payload.kind==='wheel')wheel();else if(payload.kind==='mouseMove'&&typeof payload.x==='number'&&typeof payload.y==='number')processMouseMove(payload.x,payload.y)}
function showReminder(message:string){reminderBubble.value=message;playMeow();window.setTimeout(()=>{if(reminderBubble.value===message)reminderBubble.value=''},7000)}
function checkWellness(){const now=Date.now(),stretch=settings.value.stretchReminderMinutes*60000,water=settings.value.waterReminderMinutes*60000;if(stretch>0&&now-lastStretchAt>=stretch){lastStretchAt=now;showReminder(`${ownerPrefix.value}time to stretch with me! 🐾`);idleActivity.value='stretch'}else if(water>0&&now-lastWaterAt>=water){lastWaterAt=now;showReminder(`${ownerPrefix.value}please drink some water 💧`)}}
function runInputDoctor(){doctorOpen.value=true;doctorRunning.value=true;doctorSeconds.value=5;doctorKeys.value=doctorWheels.value=doctorMoves.value=0;doctorResult.value='Type, scroll, and move the mouse in another app now.';if(doctorTimer)clearInterval(doctorTimer);doctorTimer=window.setInterval(()=>{doctorSeconds.value--;if(doctorSeconds.value<=0){if(doctorTimer)clearInterval(doctorTimer);doctorRunning.value=false;const active=nativeBridgeSeen;doctorResult.value=active?`Native hook OK · keys ${doctorKeys.value} · scroll ${doctorWheels.value} · moves ${doctorMoves.value}`:`No native events detected. Antivirus/permissions may be blocking the global hook.`}},1000)}

onMounted(async()=>{updateLife();lifeTimer=window.setInterval(updateLife,12000);reminderTimer=window.setInterval(checkWellness,15000);window.addEventListener('nyanmate-pet-settings-changed',externalSettings);window.addEventListener('mousemove',globalMouseMove);window.addEventListener('keydown',webKeyDown);window.addEventListener('wheel',webWheel,{passive:true});try{unlistenNative=await listen<NativeInputEvent>('native-input-event',e=>nativeInput(e.payload));unlistenNativeStatus=await listen<string>('native-input-status',e=>nativeInputState.value=e.payload);unlistenOpenSettings=await listen('open-pet-settings',()=>showSettings())}catch{nativeInputState.value='WebView reactions only'}})
onUnmounted(()=>{if(lifeTimer)clearInterval(lifeTimer);if(reminderTimer)clearInterval(reminderTimer);if(doctorTimer)clearInterval(doctorTimer);unlistenNative?.();unlistenNativeStatus?.();unlistenOpenSettings?.();window.removeEventListener('nyanmate-pet-settings-changed',externalSettings);window.removeEventListener('mousemove',globalMouseMove);window.removeEventListener('keydown',webKeyDown);window.removeEventListener('wheel',webWheel);void audioContext?.close()})
</script>

<template><div class="pet-customization-shell" :class="{'peek-shell':settings.peekingMode}">
<div v-if="settings.fixedMessage&&draggable" class="pet-fixed-message">📌 {{settings.fixedMessage}}</div><div v-if="reminderBubble" class="pet-reminder-bubble">{{reminderBubble}}</div><button v-if="draggable" class="pet-settings-trigger" title="Settings" @click.stop="showSettings">⚙</button>
<div class="nyan-pet" :class="[`state-${state}`,`activity-${idleActivity}`,`mood-${mood}`,`personality-${settings.personality}`,`accessory-${settings.accessory}`,`character-${settings.character}`,`pointer-${pointerDirection}`,choreographyAction?`pet-choreo-${choreographyAction}`:'',{petting:isPetting,'drag-disabled':!draggable,'mochi-drag':mochi,'cursor-hunting':hunting,'keyboard-kneading':kneading,'overheat-mode':overheat,'scroll-reaction':scrolling,'peek-mode':settings.peekingMode,'custom-fur':!!settings.customFurColor,'custom-eyes':!!settings.customEyeColor}]" :style="petStyle" @mousemove="trackEyes" @mouseleave="resetEyes" @mousedown="startDrag" @click.stop="pet" @dblclick.stop="emit('menu')" @contextmenu="openSettings" :title="lifeTitle">
<div v-if="scrolling" class="tissue-roll"><i></i></div><div v-if="overheat" class="heat-steam"><i></i><i></i><i></i></div><div v-if="purr" class="purr-bubble">prrrr ♡</div><div v-if="hunting" class="hunt-mark">⌖</div><div v-if="kneading" class="typing-mark">⌨</div>
<div class="tail"><span class="tail-tip"></span><span class="tail-stripes"></span></div><div class="body"><div class="back-patch"></div><div class="belly"></div><div class="body-markings"></div><div class="paw paw-left"></div><div class="paw paw-right"></div><div v-if="settings.accessory==='scarf'" class="scarf-knot"></div><div v-if="settings.accessory==='scarf'" class="scarf-tail"></div></div>
<div class="head"><div class="ear ear-left"><span></span></div><div class="ear ear-right"><span></span></div><div class="gray-cap"></div><div class="face-patch patch-left"></div><div class="face-patch patch-right"></div><div class="forehead-markings"></div><div class="muzzle-marking"></div><div class="eye eye-left"><i :style="{transform:`translate(${eyeX}px,${eyeY}px)`}"></i><b></b></div><div class="eye eye-right"><i :style="{transform:`translate(${eyeX}px,${eyeY}px)`}"></i><b></b></div><div class="cheek cheek-left"></div><div class="cheek cheek-right"></div><div class="nose"></div><div class="mouth"></div><div class="whiskers whiskers-left"></div><div class="whiskers whiskers-right"></div><template v-if="settings.accessory==='scarf'"><div class="scarf-band"></div><div class="scarf-badge">✦</div></template><div v-if="settings.accessory==='bell'" class="pet-bell">●</div><div v-if="settings.accessory==='bow'" class="pet-bow">◆</div><div v-if="showThought" class="thought">•••</div><div v-if="state==='coding'" class="headphones"><span></span></div><div v-if="state==='coding'" class="laptop"><span>⌘</span></div><template v-if="state==='teaching'"><div class="teacher-glasses"><span></span><span></span></div><div class="graduation-cap"><i></i></div><div class="teaching-pointer"></div></template><div v-if="showSparkles" class="sparkles">✦ ✧</div><div v-if="state==='error'" class="alert">!</div><div v-if="state==='sleeping'||idleActivity==='doze'" class="sleep-z">Z z</div><div v-if="mood==='playful'&&autonomous" class="mood-heart">♥</div><div v-if="mood==='curious'&&autonomous" class="mood-mark">?</div></div><div v-if="draggable" class="pet-name-tag">{{settings.name}}</div></div>

<div v-if="settingsOpen" class="pet-settings-popover pet-settings-v28" @click.stop @mousedown.stop><div class="pet-settings-head"><strong>⚙ NyanMate Settings</strong><button @click="settingsOpen=false">×</button></div><label>Cat name<input v-model="draft.name" maxlength="24"/></label><label>Your name<input v-model="draft.ownerName" maxlength="32" placeholder="Used in reminders"/></label><label>Character<select v-model="draft.character"><option v-for="cat in petCharacters" :key="cat" :value="cat">{{characterLabels[cat]}}</option></select></label><div class="cat-preview-grid"><button v-for="cat in petCharacters" :key="cat" :class="['cat-swatch',`swatch-${cat}`,{active:draft.character===cat}]" @click="draft.character=cat"><i></i><span>{{characterLabels[cat].split(' · ')[0]}}</span></button></div><label>Personality<select v-model="draft.personality"><option value="gentle">Gentle</option><option value="playful">Playful</option><option value="focused">Focused</option><option value="sleepy">Sleepy</option></select></label><label>Accessory<select v-model="draft.accessory"><option value="scarf">Signature scarf</option><option value="bell">Bell</option><option value="bow">Bow</option><option value="none">None</option></select></label><div class="appearance-grid"><label>Custom fur<input v-model="draft.customFurColor" type="color"/></label><label>Eye color<input v-model="draft.customEyeColor" type="color"/></label></div><button class="clear-colors" @click="draft.customFurColor='';draft.customEyeColor=''">Use character colors</button><label>Sound volume <span>{{draft.soundVolume}}%</span><input v-model.number="draft.soundVolume" type="range" min="0" max="100"/></label><label>Fixed message<input v-model="draft.fixedMessage" maxlength="120" placeholder="Pinned above the cat"/></label><div class="pet-reminder-grid"><label>Stretch every<input v-model.number="draft.stretchReminderMinutes" type="number" min="0" max="720"/><small>minutes · 0 = off</small></label><label>Water every<input v-model.number="draft.waterReminderMinutes" type="number" min="0" max="720"/><small>minutes · 0 = off</small></label></div><label>Motion<select v-model="draft.motionLevel"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option></select></label><label>Sleep after <span>{{draft.sleepAfterMinutes}} min</span><input v-model.number="draft.sleepAfterMinutes" type="range" min="1" max="30"/></label><div class="reaction-toggles"><label><input v-model="draft.autonomousMovement" type="checkbox"/> Autonomous movement</label><label><input v-model="draft.cursorHunting" type="checkbox"/> Hunt fast cursor</label><label><input v-model="draft.keyboardReactions" type="checkbox"/> Keyboard kneading + overheat</label><label><input v-model="draft.scrollReactions" type="checkbox"/> Scroll tissue reaction</label><label><input v-model="draft.peekingMode" type="checkbox"/> Peeking mode</label></div><div class="native-input-status">⌨ {{nativeInputState}}</div><button class="doctor-button" @click="runInputDoctor">🩺 Run 5s Input Doctor</button><div v-if="doctorOpen" class="doctor-card"><strong>{{doctorRunning?`Testing… ${doctorSeconds}s`:'Input Doctor'}}</strong><span>{{doctorResult}}</span><small>Keys {{doctorKeys}} · Scroll {{doctorWheels}} · Mouse {{doctorMoves}}</small></div><div class="pet-settings-actions"><button @click="draft={...defaultPetSettings}">Defaults</button><button class="primary" @click="applySettings">Save</button></div><small>Windows native input only reports event types and pointer coordinates; typed characters are not captured.</small></div></div></template>
